'use strict';
window.CareFlow=(()=>{
 const el=id=>document.getElementById(id),e=v=>esc(String(v??'')),call=(p,body,method='POST')=>API.call(p,body===undefined?{}:{method,body});
 const q=()=>new URLSearchParams(location.hash.split('?')[1]||''),subject=()=>API.actingFor?.id||API.me?.id;
 let generation=0,data=null,seriesData=null,activeTask=null,activeSubject=null,lastInput=0;
 const button=(action,label,id='')=>`<button type="button" class="btn btn-secondary btn-sm" data-flow-action="${action}" data-id="${e(id)}">${e(label)}</button>`;
 const field=(name,label,value='',type='text',extra='')=>`<label>${e(label)}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
 const area=(name,label,value='',extra='')=>`<label>${e(label)}<textarea name="${name}" rows="4" ${extra}>${e(value)}</textarea></label>`;
 const select=(name,label,options,value='')=>`<label>${e(label)}<select name="${name}">${options.map(([v,t])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
 const check=(name,label)=>`<label><input type="checkbox" name="${name}" required> ${e(label)}</label>`;
 const form=(name,content,label='Save',attrs='')=>`<form class="flow-form" data-flow-form="${name}" ${attrs}>${content}<button class="btn btn-primary" type="submit">${e(label)}</button><p role="status" data-flow-status></p></form>`;
 const card=(title,content)=>`<article class="flow-card"><h2>${e(title)}</h2>${content}</article>`;
 const empty=s=>`<p class="flow-muted">${e(s)}</p>`;
 const visit=v=>`<b>${e(fmtAU(v.date))} at ${e(v.start)}</b> · ${Number(v.hours)} hours · ${e(v.status)}`;
 const link=(panel,label,extra='')=>`<a class="btn btn-secondary btn-sm" href="#/journey?panel=${panel}${extra}">${e(label)}</a>`;
 function status(f,msg,bad=false){const s=f.querySelector('[data-flow-status]');if(s){s.textContent=msg;s.classList.toggle('flow-error',bad);}}
 function snapshot(){return `${API.me?.id}:${subject()}`;}
 function dialog(title,html,label='Confirm',read=()=>true){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='flow-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<h2>${e(title)}</h2>${html}<p role="alert" class="flow-error"></p><div class="flow-actions">${button('dialog-confirm',label)}${button('dialog-cancel','Go back')}</div>`;document.body.append(d);const prev=document.activeElement;let done=false;function finish(v){if(done)return;done=true;d.close();d.remove();if(prev?.isConnected)prev.focus?.({preventScroll:true});resolve(v);}d.oncancel=ev=>{ev.preventDefault();finish(null);};d.querySelector('[data-flow-action=dialog-cancel]').onclick=()=>finish(null);d.querySelector('[data-flow-action=dialog-confirm]').onclick=()=>{try{finish(read(d));}catch(err){d.querySelector('[role=alert]').textContent=err.message;}};d.showModal();});}
 function brief(b){if(!b)return empty('No current brief is available.');return `<p>Support plan version ${e(b.version)}</p>${(b.sections||[]).map(s=>`<details open><summary>${e(s.title)}</summary><p class="flow-brief">${e(s.body)}</p></details>`).join('')}${b.emergency?`<p>Emergency contact: ${e(b.emergency.name)} · ${e(b.emergency.phone)}</p>`:''}${(b.specialised||[]).map(s=>`<p>${e(s.label)}: ${s.yes?'Yes':'No'}</p>`).join('')}${(b.plans?.plans||[]).map(p=>`<p><a href="${e(p.url||'/api/participant-documents/'+p.id+'/file')}" target="_blank" rel="noopener noreferrer">${e(p.label||p.name||'Shared clinical plan')}</a></p>`).join('')}`;}
 async function render(){
   const root=el('flowContent');if(!root)return;const gen=++generation,context=snapshot(),hash=location.hash;
   if(!API.me){root.innerHTML=card('Sign in to continue','<p>Sign in to see your next steps.</p>'+button('login','Sign in'));return;}
   root.innerHTML=empty('Loading your next steps…');
   try{const target=Number(q().get('for'));if(API.me.role==='coordinator'&&target&&target!==subject()){const d=await API.call('/coordinator/clients',{noFor:true});const client=d.clients.find(x=>x.id===target);if(!client)throw Error('Access to this person is no longer available.');API.actingFor=client;return render();}data=API.me.admin && (q().get('panel')||'tasks')==='tasks'?{role:'office',subject:null}:await call('/journey');if(gen!==generation||context!==snapshot()||hash!==location.hash)return;
     el('flowPerson').textContent=data.role==='coordinator'&&data.subject?`For ${data.subject.name}`:data.role==='office'?'Office workspace':'';
     const worker=data.role==='worker',office=data.role==='office',panel=q().get('panel')||'tasks';
     const canonical=canonicalPanel(panel,worker);
     if(!office && canonical){root.innerHTML=card('Opening settings',`<p><a href="${e(canonical)}">Continue to your settings</a></p>`);location.hash=canonical;return;}
     let tabs=office?[['tasks','All tasks'],['recruitment','Recruitment'],['payroll','Pay batches'],['deliveries','Messages'],['transitions','Transitions'],['finance','Invoice exceptions'],['metrics','Time and progress'],['settings','Setup']]:[['tasks','Next actions'],...(worker?[['recruitment','Application'],['payroll','Pay status']]:[['routines','Usual visits'],['reviews','Timesheets'],['transitions','Change support']]),['renewals','Upcoming renewals']];
     if(data.role==='coordinator'){tabs.splice(1,0,['intake','Person’s details'],['billing','Funding']);const required={intake:'plan',billing:'invoices',routines:'bookings',reviews:'bookings',transitions:'bookings',renewals:'documents'};tabs=tabs.filter(([id])=>!required[id]||data.scopes?.includes(required[id]));}
     const title=panel==='tasks'?'Next actions':tabs.find(([id])=>id===panel)?.[1]||({shift:'Visit details',series:'Repeating visits',followup:'Visit feedback'}[panel]||'Next actions');
     const heading=el('flowTitle');if(heading)heading.textContent=title;document.title=title+' — The Care Web';
     el('flowTabs').innerHTML=(panel!=='tasks'?'<a class="na-back" href="#/journey">← Next actions</a>':'')+`<details class="na-tools"><summary>${office?'Office tools':data.role==='coordinator'?'Tools for this person':'More tools'}</summary><div class="na-tool-links">${tabs.filter(([id])=>id!=='tasks').map(([id,title])=>`<a href="#/journey?panel=${id}" ${id===panel?'aria-current="page"':''}>${title}</a>`).join('')}</div></details>`;
     const html=await panels[panel]?.()||await panels.tasks();if(gen!==generation||context!==snapshot()||hash!==location.hash)return;root.innerHTML=html;
     if(panel==='shift'){const f=root.querySelector('[data-note-form]');if(f)await BookItReview.loadDraft(f);}
   }catch(err){if(gen===generation&&hash===location.hash)root.innerHTML=card('Could not load this page',`<p class="flow-error">${e(err.message)}</p>${button('refresh','Try again')} ${API.me?.role==='coordinator'?'<a href="#/clients">Choose a person</a>':'<a href="#/contact">Contact us</a>'}`);}
 }
 const panels={};
 panels.tasks=async()=>data.role==='office'?officeTasks():CareNextActions.render(data,taskDestination);
 function canonicalPanel(panel,worker){
   // Delegates edit their selected person's information, not their own profile.
   if(API.me?.role==='coordinator' && ['intake','billing'].includes(panel))return null;
   if(panel==='intake')return API.me?.role==='coordinator'?'#/support-plan':'#/account/profile';
   if(panel==='uploads')return worker?'#/account/credentials'+(q().get('type')?'?type='+encodeURIComponent(q().get('type')):''):'#/account/documents';
   if(panel==='billing')return API.me?.role==='coordinator'?'#/clients':'#/account/billing';
   if(panel==='preferences')return '#/account/notifications';
   return null;
 }
 function taskDestination(t){
   if(API.me?.role==='coordinator'&&String(t.destination).startsWith('#/account/documents'))return '#/clients';
   if(t.task_key.includes('billing'))return API.me?.role==='coordinator'?'#/journey?panel=billing':'#/account/billing';
   const old=/^#\/journey\?panel=uploads(?:&type=([^&]+))?/.exec(t.destination||'');
   if(old)return '#/account/credentials'+(old[1]?'?type='+old[1]:'');
   if(t.owner_kind==='office'&&t.destination==='#/journey')return '#/journey?panel=tasks';
   return t.destination;
 }
 async function officeTasks(){
   const p=await call('/admin/journey-queue?offset='+(Number(q().get('offset'))||0)+'&q='+encodeURIComponent(q().get('search')||''));
   const unassigned=p.rows.filter(t=>!t.owner_id).length,today=p.today||new Date().toISOString().slice(0,10);
   const destination=t=>t.kind==='recruitment'?'#/journey?panel=recruitment&worker='+Number(t.user_id):t.kind==='transition'?'#/journey?panel=transitions':(t.task_key.startsWith('office:')||String(t.destination).startsWith('#/journey?panel=shift&'))?t.destination:'#/admin/verification?role='+(t.person_role==='participant'?'participant':'worker')+'&person='+Number(t.user_id);
   return `<div class="na-office"><div class="na-office-bar"><div><h2>${p.total} open task${p.total===1?'':'s'}</h2><p class="na-office-meta">${p.rows.length?`${p.offset+1}–${p.offset+p.rows.length} shown · ${unassigned} unassigned on this page`:'No tasks match this search.'}</p></div>${form('queue-search',field('search','Find a person or task',q().get('search')||''),'Search')}</div><div class="na-office-list">${p.rows.map(t=>`<article class="na-office-row"><div class="na-office-line"><div><h3>${e(t.label)}</h3><p><b>${e(t.person)}</b>${t.due_at?' · '+(t.due_at.slice(0,10)<today?'Overdue — ':'Due ')+e(fmtAU(t.due_at.slice(0,10))):''}</p><span class="na-office-meta">${e(p.staff.find(s=>s.id===t.owner_id)?.name||'Unassigned')}</span></div><a class="na-action" href="${e(destination(t))}">Open record</a></div><details><summary>Details & assignment</summary>${t.detail?`<p class="na-office-meta">${e(t.detail)}</p>`:''}<p class="na-office-meta">Waiting since ${e(new Date(t.ready_at).toLocaleString('en-AU'))}</p>${form('task-owner',select('owner_id','Office owner',[[0,'Unassigned'],...p.staff.map(x=>[x.id,x.name])],t.owner_id||0)+field('due_at','Due date',t.due_at?.slice(0,10)||'','date'),'Save assignment',`data-key="${e(t.task_key)}"`)}</details></article>`).join('')}</div><div class="flow-actions">${p.offset?link('tasks','Previous','&offset='+Math.max(0,p.offset-100)+'&search='+encodeURIComponent(q().get('search')||'')):''}${p.offset+100<p.total?link('tasks','Next','&offset='+(p.offset+100)+'&search='+encodeURIComponent(q().get('search')||'')):''}</div></div>`;
 }
 panels.intake=async()=>{const d=await call('/journey/intake');return card('Confirm your shared details',`<p>These details are reused in setup. Check them before saving. A confirmed support plan changes only when you review and submit it.</p>${d.updated_at?`<p class="flow-muted">Last saved ${e(new Date(d.updated_at).toLocaleString('en-AU'))}</p>`:''}${form('intake',field('name','Name',d.data.name,'text','required autocomplete="name"')+field('phone','Phone',d.data.phone,'tel','autocomplete="tel"')+field('suburb','Suburb',d.data.suburb)+field('ec_name','Emergency contact name',d.data.ec_name)+field('ec_phone','Emergency contact phone',d.data.ec_phone,'tel')+field('ec_relationship','Relationship',d.data.ec_relationship)+area('contact_preferences','How you prefer to be contacted',d.data.contact_preferences),'Confirm and save',`data-revision="${d.revision}" data-account-revision="${e(d.account_revision)}"`)}${data.role!=='worker'?'<p><a href="#/support-plan">Review the support plan using these details</a></p>':''}`);};
 panels.billing=async()=>{const d=await call('/me/billing'),u=d.user||d;return card('How your support is paid',`<p>Private funding is separate from an unknown funding arrangement. Issued invoices retain their original payer details.</p>${form('billing',select('plan','Funding',[['','Choose funding'],['private','Private — I pay directly'],['self','NDIS self-managed'],['plan','NDIS plan-managed'],['ndia','NDIA-managed']],u.plan)+field('ndis_number','NDIS number (NDIS only)',u.ndis_number)+field('pm_email','Plan manager email (plan-managed only)',u.pm_email,'email')+field('plan_start','Plan starts (NDIS only)',u.plan_start,'date')+field('plan_end','Plan ends (NDIS only)',u.plan_end,'date'),'Review and save')}`);};
 async function documentAssistance(docs=[]){
   const ai=await call('/journey/assistance').catch(()=>({enabled:false,suggestions:[]}));CareFlow.ai=ai;
   if(!ai.enabled && !ai.suggestions?.length)return '';
   return `<details class="cred-additional"><summary>Optional document assistance</summary><p>After uploading a file, use Read date and number to propose details. Check every suggestion against the original.</p>${ai.enabled?docs.filter(d=>d.has_file&&!d.verified_at).map(d=>`<p>${e(d.file_name || d.type_label)} ${button('assist-document','Read date and number',d.id)}</p>`).join(''):''}${(ai.suggestions||[]).filter(s=>s.status==='review').map(s=>card('Check suggested details',`<p>Document #${s.doc_id}. Confidence ${Math.round(s.result.confidence*100)}%.</p><blockquote>${e(s.result.source_text||'Check the original document.')}</blockquote>${form('assist-review',field('expiry_date','Expiry date',s.result.expiry_date,'date')+field('check_number','Check number',s.result.check_number)+select('decision','Your decision',[['modified','Save my checked values'],['accepted','Accept checked suggestions'],['rejected','Reject suggestions']])+check('confirm','I checked these values against the original document.'),'Save review',`data-id="${s.id}"`)}`)).join('')}</details>`;
 }
 async function renderAccountExtra(root,build){if(!root)return;const context=snapshot(),hash=location.hash;root.innerHTML=empty('Loading…');try{const html=await build();if(context===snapshot()&&hash===location.hash)root.innerHTML=html;}catch(err){if(context===snapshot()&&hash===location.hash)root.innerHTML=card('Could not load these settings',`<p>${e(err.message)}</p>${button('refresh-account','Try again')}`);}}
 async function renderContacts(root){return renderAccountExtra(root,async()=>{const d=await call('/journey/intake');return card(API.me.role==='worker'?'Emergency contact & contact notes':'Contact notes',form('shared-contacts',(API.me.role==='worker'?field('ec_name','Emergency contact name',d.data.ec_name)+field('ec_phone','Emergency contact phone',d.data.ec_phone,'tel')+field('ec_relationship','Relationship',d.data.ec_relationship):'<p>Your emergency contact is managed in your <a href="#/support-plan">support plan</a>.</p>')+area('contact_preferences','Additional contact instructions',d.data.contact_preferences),'Save contact details',`data-revision="${d.revision}"`));});}
 async function renderPreferences(root){return renderAccountExtra(root,panels.preferences);}
 async function refreshCurrent(){
   if(location.hash.startsWith('#/account/credentials'))return WorkerCredentials.render(el('miniCreds'));
   if(location.hash.startsWith('#/account/notifications'))return renderPreferences(el('miniWorkflowPreferences'));
   if(location.hash.startsWith('#/account/profile'))return renderContacts(el('miniSharedContacts'));
   return render();
 }
 panels.renewals=async()=>{const d=await call('/journey/renewals');return card('Upcoming renewals',`<p>These visits may be affected if the required renewal is not completed and reviewed. The existing safety checks still apply.</p>${d.rows.map(r=>`<article class="flow-card"><h3>${e(r.label)}</h3><p>Expires ${e(fmtAU(r.expires))}</p><a class="btn btn-primary btn-sm" href="${e(r.destination)}">Open renewal task</a><details><summary>${r.affected.length} visits on or after expiry</summary>${r.affected.map(v=>`<p>${visit(v)} ${link('shift','Open','&booking='+v.id)}</p>`).join('')}</details></article>`).join('')||empty('No renewals due in the next 60 days.')}`)+card('Received and awaiting review',d.received.map(x=>`<p>${e(x.type)} · ${e(x.expiry_date||'No expiry supplied')}</p>`).join('')||empty('No received documents waiting for review.'));};
 panels.recruitment=async()=>{const office=data.role==='office',wid=q().get('worker');if(office&&!wid){const d=await call('/admin/journey-queue?q=review');return card('Worker applications',form('choose-worker',field('worker','Worker ID','','number','min="1" required'),'Open application')+d.rows.filter(x=>x.kind==='recruitment').map(t=>`<p>${e(t.person)} ${link('recruitment','Open','&worker='+t.user_id)}</p>`).join(''))+card('Offer an interview time',form('interview-slot',field('starts_at','Starts','','datetime-local','required')+field('ends_at','Ends','','datetime-local','required'),'Create slot'));}
   const d=await call('/journey/recruitment'+(office?'?worker='+Number(wid):''));return card(d.worker.name+' — application',`<p>Interviews, references and employment arrangements are reviewed by the office. Document uploads have their own checklist.</p>${['interview','references','employment'].map(k=>{const ch=d.checks.find(x=>x.check_key===k);return `<article class="flow-card"><h3>${e(k[0].toUpperCase()+k.slice(1))}</h3><p>${e(ch?.status||'Awaiting review')}</p>${office?form('recruit-review',select('status','Outcome',[['pending','Pending'],['needs-information','Needs information'],['complete','Complete']],ch?.status)+area('evidence','Evidence and review outcome',ch?.evidence,'required minlength="15"'),'Record review',`data-worker="${d.worker.id}" data-key="${k}"`):''}</article>`;}).join('')}${office?`<p>${e(d.missing.join(', '))}</p>${button('activate-worker','Activate reviewed worker',d.worker.id)}`:''}`)+(!office?card('Book your interview',d.slots.length?d.slots.map(s=>`<p>${e(new Date(s.starts_at).toLocaleString('en-AU'))} — ${e(new Date(s.ends_at).toLocaleTimeString('en-AU'))} ${s.worker_id===API.me.id?button('cancel-interview','Cancel / reschedule'): `<button class="btn btn-secondary btn-sm" data-flow-action="book-interview" data-id="${s.id}" data-revision="${s.revision}">Choose time</button>`}</p>`).join(''):empty('The office will publish available times here.')):'');};
 panels.shift=async()=>{const id=Number(q().get('booking'));const d=await call('/journey/bookings/'+id),b=d.booking,worker=data.role==='worker';CareFlow.shift=d;let actions='';if(worker&&b.status==='requested')actions=button('accept-visit','Review and accept',id)+button('decline-visit','Decline',id)+(b.series_id?link('series','Review repeating dates','&series='+b.series_id):'');
   const note=worker&&b.status==='accepted'?card('Record this shift',`<p>Your draft saves while you type. Record what actually happened; completion files the note.</p><div class="note-box flow-form" data-note-form="${id}"><label>Support delivered and outcome<textarea class="note-body" maxlength="4000" rows="6"></textarea></label><label><input type="radio" name="bkScope${id}" value="no" checked> No change or scope concern to flag</label><label><input type="radio" name="bkScope${id}" value="yes"> Flag a support or scope concern</label><label>Concern details<textarea class="note-scope-detail" maxlength="4000" rows="3"></textarea></label>${b.sleepover?'<label>Actual active hours<input class="note-active" type="number" min="0" max="24" step="0.25"></label><label>Active support details<textarea class="note-active-note" rows="3" maxlength="2000"></textarea></label>':''}<details><summary>Participant transport during this shift</summary><p>Record participant transport only. Do not include commuting to or from work.</p><label>Kilometres<input class="note-km" type="number" min="0" step="0.1" value="0"></label><label>Trip started<input class="note-km-from" maxlength="80"></label><label>Trip finished<input class="note-km-to" maxlength="80"></label></details><p class="review-note-state" role="status"></p><button type="button" class="btn btn-secondary btn-sm" data-draft-save>Save draft / retry</button>${button('complete-visit','Save note and complete shift',id)}</div>`):'';
   const review=b.status==='completed'&&b.approval_state==='pending'&&!worker?card('Review this timesheet',`<p>Read the time, charge and filed note before deciding. Approval starts invoice processing automatically.</p>${window.automaticChargeDetails?automaticChargeDetails(b):''}<p>${Number(b.hours)} hours · Support charge $${Number(b.total||0).toFixed(2)} · Travel $${Number(b.km_total||0).toFixed(2)}</p>${button('approve-visit','Approve timesheet',id)}${form('query-visit',area('question','Ask a question','','required minlength="5"'),'Send question',`data-id="${id}"`)}`):'';
   const reply=worker&&b.approval_state==='queried'?card('Answer the question',`<p>${e(b.query_text||b.query_note||'Read the question in the filed notes below.')}</p>${form('reply-query',area('body','Your answer','','required minlength="5"'),'Send answer',`data-id="${id}"`)}`):'';
   return `<p><a href="#/bookings?view=calendar${/^\d{4}-\d{2}-\d{2}$/.test(q().get('return_date')||'')?'&amp;date='+e(q().get('return_date')):''}">← Back to calendar</a> · <a href="#/bookings?view=list&amp;booking=${id}">Cancellation and other booking controls</a></p>`+(d.scope?card('Agreed support arrangements',d.scope.ready?`<p>${e(d.scope.handoff.arrangement)}</p><p>Contact: ${e(d.scope.handoff.contact)}</p><p>When: ${e(d.scope.handoff.timing)}</p><p>Excluded activities: ${d.scope.warning.labels.map(e).join(', ')}. Contact the office if the arrangement fails; do not undertake excluded activities.</p>`:'<p>The office must confirm arrangements for excluded support before this visit is accepted. Contact the office for help.</p>'):'')+card('Visit with '+d.other_name,`<p>${visit(b)}</p><p>${e(b.service)} · Visit #${id}</p><div class="flow-actions">${actions}${!worker?button('book-again','Book again',id)+button('save-routine','Save as a usual visit',id):''}<a href="#/messages" class="btn btn-secondary btn-sm">Messages</a></div>`)+(d.brief?card('Current support brief',`<details><summary>Read support plan version ${e(d.plan_version)}</summary>${brief(d.brief)}</details>${worker?button('plan-changes','See changes since my last review',id):''}`):'')+note+card('Filed notes',d.notes.map(n=>`<p class="flow-muted">${e(n.kind)} · ${e(new Date(n.created).toLocaleString('en-AU'))}</p><p class="flow-brief">${e(n.body)}</p>`).join('')||empty('No completed notes yet.'))+review+reply+card('Report an incident',`<details><summary>Open incident report for this visit</summary>${form('incident',select('category','Category',[['near-miss','Near miss'],['serious-injury','Serious injury'],['abuse-neglect','Abuse or neglect'],['restrictive-practice','Unauthorised restrictive practice'],['death','Death'],['unlawful-contact','Unlawful contact'],['sexual-misconduct','Sexual misconduct'],['other','Other']])+field('occurred_at','When did it occur?','','datetime-local')+field('provider_aware_at','When did the provider become aware?','','datetime-local')+select('harm','Was there harm?',[['unknown','Not yet known'],['yes','Yes'],['no','No']])+area('description','What happened?','','required maxlength="4000"')+area('immediate_action','What action did you take?','','maxlength="2000"'),'File incident',`data-id="${id}" data-event="${crypto.randomUUID()}"`)}</details>`);};
 panels.series=async()=>{seriesData=await call('/journey/series/'+Number(q().get('series')));return card('Review repeating visits',`<p>Choose each date you can work. Availability, travel and the current plan are checked again when you accept.</p><div class="flow-form" id="flowSeries">${seriesData.visits.map(v=>`<label><input type="checkbox" value="${v.id}" name="visit"> ${e(fmtAU(v.date))} at ${e(v.start)} · ${v.hours} hours · estimated pay $${Number(v.pay).toFixed(2)}</label>`).join('')}<details open><summary>Read plan version ${e(seriesData.plan_version)}</summary>${brief(seriesData.brief)}</details><label><input type="checkbox" name="read"> I have read and can follow this plan version.</label>${button('accept-series','Accept selected dates',q().get('series'))}</div>`);};
 panels.routines=async()=>{const d=await call('/journey/routines');CareFlow.routines=d.routines;return card('Your usual visits',`<p>A usual visit remembers the worker, service, time and length. Choose a new date and review it before requesting. Previous care notes are never copied.</p>${d.routines.map(r=>`<article class="flow-card"><h3>${e(r.label)}</h3><p>${e(r.data.service)} · ${e(r.data.start)} · ${r.data.hours} hours</p>${button('use-routine','Choose new date',r.id)} ${button('delete-routine','Remove',r.id)}</article>`).join('')||empty('Open a visit and choose “Save as a usual visit”.')}`);};
 panels.reviews=async()=>{const d=await call('/bookings');const pending=d.bookings.filter(b=>b.status==='completed'&&['pending','queried'].includes(b.approval_state));return card('Timesheets to review',`<p>Review each visit individually. You can approve it or ask a question without losing your place.</p>${pending.map(b=>`<article class="flow-card"><p>${visit(b)} · ${e(b.other_name)}</p><p>${e(b.approval_state)} · $${Number(b.total||0).toFixed(2)}</p>${link('shift','Read note and review','&booking='+b.id)}</article>`).join('')||empty('No timesheets waiting for you.')}`);};
 panels.followup=async()=>card('How did it go?',form('followup',select('answer','What would you like next?',[['continue','Continue with this worker'],['change','Find a different match'],['help','Speak with the office']])+area('note','Anything you want us to know?','','maxlength="1000"'),'Send',`data-id="${Number(q().get('booking'))}"`));
 panels.preferences=async()=>{const [d,feeds]=await Promise.all([call('/journey/preferences'),call('/journey/calendar')]);return card('Notification preferences',form('preferences',`<label><input name="digest" type="checkbox" ${d.preferences.digest?'checked':''}> Combine routine updates into a daily email</label>`+field('quiet_from','Quiet hours start (site timezone)',d.preferences.quiet_from,'time')+field('quiet_to','Quiet hours end (site timezone)',d.preferences.quiet_to,'time')+(d.approvers.length?select('approval_owner','Who should receive timesheet reminders?',d.approvers.map(x=>[x.id,x.name]),d.approval_owner):''))+`<p class="flow-muted">Urgent cover, safety and security messages bypass quiet hours.</p>`)+card('Calendar subscription',`<p>Your calendar receives visit times with a generic title. No care notes, names or addresses are included. The secret link expires after 90 days; replacing or revoking it stops future access.</p>${button('create-calendar','Create a private calendar link')}<div id="flowCalendarLink" role="status"></div>${feeds.feeds.filter(f=>!f.revoked_at).map(f=>`<p>Feed #${f.id}, expires ${e(fmtAU(f.expires_at.slice(0,10)))} ${button('revoke-calendar','Revoke',f.id)}</p>`).join('')}`);};
 panels.transitions=async()=>{if(data.role==='office'){const d=await call('/admin/transitions');return card('Support changes and handovers',d.cases.map(t=>`<article class="flow-card"><h3>${e(t.name)} · ${e(t.kind)}</h3><p class="flow-brief">${e(t.reason)}</p><p>${t.impact.future.length} future visits · ${t.impact.queries.length} open questions · ${t.impact.unpaid.length} unpaid invoices · ${t.impact.outstanding_notes.length} visits awaiting notes</p>${t.impact.outstanding_notes.map(v=>`<p>Complete visit #${v.id} · ${e(v.date)}</p>`).join('')}<details><summary>Invoice and access checklist</summary>${t.impact.unpaid.map(i=>`<p>${e(i.invoice_no)}</p>`).join('')}${t.impact.helpers.map(h=>`<p>${e(h.name)} · ${e(h.scopes)}</p>`).join('')}</details>${t.impact.future.map(v=>`<p>${visit(v)} · #${v.id}</p>`).join('')}${form('transition-close',field('owner_id','Office owner ID',t.owner_id||API.me.id,'number','required')+area('outcome','Agreed outcome, handover and invoice follow-up','','required minlength="25"')+check('confirm','I reviewed every listed future visit and agreed the arrangements with the participant.'),'Close reviewed handover',`data-id="${t.id}" data-visits="${t.impact.future.map(v=>v.id).join(',')}"`)}</article>`).join('')||empty('No open changes.'));}
   const d=await call('/journey/transition');CareFlow.transition=d;return card('Change your support',`<p>Ask the office to help with a change or handover. Your visits stay scheduled until the arrangements are agreed.</p>${form('transition',select('kind','What do you need?',[['change-worker','Change worker'],['end-support','End support'],['handover','Arrange a handover']])+area('reason','Tell us what you need','','required minlength="10"'),'Ask the office')}`)+card('Current arrangements',`${d.future.map(v=>`<p>${visit(v)} ${link('shift','Open','&booking='+v.id)}${v.series_id?button('end-series','Review ending series',v.series_id):''}</p>`).join('')||empty('No future visits.')}<p>${d.queries.length} open timesheet questions · ${d.outstanding_notes.length} visits awaiting notes.</p><p><a href="#/statements">Statements and invoices</a> · <a href="#/access">Review helper access</a></p>`)+card('Change requests',d.cases.map(t=>`<p>${e(t.kind)} · ${e(t.state)} · ${e(t.reason)}</p>`).join('')||empty('No requests yet.'));};
 panels.payroll=async()=>{if(data.role!=='office'){const d=await call('/journey/payroll');return card('Your pay preparation',`<p>Exported means sent to the payroll process. Payment recorded means the office has recorded an external payment reference.</p>${d.lines.map(l=>`<p>${e(l.source_key)} · $${Number(l.amount).toFixed(2)} · ${e(l.status)} · ${e(l.batch_status)}${l.resolution?' — '+e(l.resolution):''}</p>`).join('')||empty('No pay batch lines yet.')}`);}
   const id=q().get('batch');if(!id){const d=await call('/admin/payroll-batches');return card('Prepare a pay batch',`<p>Unbatched work from the last 14 days is prepared daily. Use a date range to collect older work. Review exceptions and pay obligations before exporting.</p>${form('payroll-prepare',field('from','From','','date','required')+field('to','To','','date','required'),'Prepare draft')}`)+d.batches.map(b=>card('Batch #'+b.id,`<p>${e(fmtAU(b.from_date))} – ${e(fmtAU(b.to_date))} · ${e(b.status)} · ${b.line_count} lines · ${b.exceptions} exceptions</p>${link('payroll','Open batch','&batch='+b.id)}`)).join('');}
   const b=await call('/admin/payroll-batches/'+Number(id));return card('Pay batch #'+b.id,`<p>${e(b.status)} · ${e(fmtAU(b.from_date))} – ${e(fmtAU(b.to_date))}</p>${b.lines.map(l=>`<article class="flow-card"><h3>${e(l.data.worker)} · $${Number(l.amount).toFixed(2)}</h3><p>Line #${l.id} · ${e(l.source_key)} · ${e(l.data.type)} · ${e(l.data.date)} · ${e(l.status)}</p><p>${e(l.exception)} ${e(l.resolution)}</p>${b.status==='draft'?form('payroll-line',select('status','Treatment',[['included','Include'],['excluded','Exclude with reason']],l.status)+field('gross_wages','Reviewed gross wages',l.components?.gross_wages??'','number','step="0.01"')+field('super','Reviewed super',l.components?.super??'','number','step="0.01"')+field('allowances','Reviewed allowances',l.components?.allowances??'','number','step="0.01"')+field('payroll_reference','External payroll calculation reference',l.components?.reference||'')+area('reason','Decision and evidence',l.resolution,'required minlength="15"'),'Record review',`data-id="${l.id}"`):''}</article>`).join('')}${b.status==='draft'?button('approve-payroll','Review and approve batch',b.id)+`<details><summary>Add an adjustment</summary>${form('payroll-adjustment',field('worker_id','Worker ID','','number','required')+field('amount','Signed amount','','number','required step="0.01"')+field('reference','Unique adjustment reference','','text','required')+area('reason','Reason','','required minlength="15"'),'Add adjustment',`data-id="${b.id}"`)}</details>`:''}${['approved','exported','acknowledged'].includes(b.status)?`<p><a class="btn btn-secondary" href="/api/admin/payroll-batches/${b.id}.csv">Download batch CSV</a></p>${b.status==='approved'?button('reopen-payroll','Reopen before export',b.id):''}${button('refresh','Refresh export status')}`:''}${b.status==='exported'?form('payroll-ack',field('external_ref','External payment / payroll reference','','text','required minlength="5"')+check('confirm','I have checked the external payment result for this batch.'),'Record payment result',`data-id="${b.id}"`):''}`);};
 panels.deliveries=async()=>{const d=await call('/admin/deliveries');return card('Message delivery',`<p>Email transport is <b>${d.email_enabled?'enabled':'not configured'}</b>. “Sent” means accepted by the email transport. Failed messages remain visible here.</p>${d.rows.map(r=>`<article class="flow-card"><b>${e(r.kind||'Email')} · ${e(r.status)}</b><p>${e(r.recipient)} · ${r.attempts} attempts</p><p>${e(r.error)}</p>${['failed','retry','queued'].includes(r.status)?button('retry-delivery','Retry',r.id):''}</article>`).join('')||empty('No queued messages.')}`);};
 panels.finance=async()=>{const d=await call('/admin/finance-exceptions');return card('Billing and payment review','<p><a href="#/admin/assurance?tab=billing">Review charge lines, refunds and reversals</a></p>')+card('Provider events needing reconciliation',(d.provider_events||[]).map(x=>`<article class="flow-card"><p>${e(x.event_type)} · ${e(x.invoice_no||'Invoice not linked yet')} · ${e(x.event_id)}</p>${form('provider-review',area('note','Provider result and reconciliation outcome','','required minlength="30"')+field('receipt_reference','Ledger reference (if a refund/reversal was recorded)')+check('confirm','I checked the provider and the invoice ledger.'),'Record event review',`data-event="${e(x.event_id)}"`)}</article>`).join('')||empty('No provider events awaiting review.'))+ card('Invoices and delivery',`<p>Keep issuing, delivery and payment status separate. The office records reconciled receipts in the invoice register.</p><a href="#/admin/money">Open invoice register</a>${d.invoices.map(i=>`<p>${e(i.invoice_no)} · ${e(i.claim_status)} · $${Number(i.total||0).toFixed(2)} · ${e(i.payer)} · delivery ${e(i.delivery_status||'not queued')} ${link('deliveries','Check delivery')}</p>`).join('')}`)+card('Work not yet invoiced',d.unissued.map(b=>`<p>Visit #${b.id} · ${e(b.date)} · ${e(b.funding)} · ${e(b.approval_state||'needs review')}${b.claim_hold?' · Held: '+e(b.hold_reason):''}</p>`).join('')||empty('No unissued work.'))+card('Record payment evidence',form('receipt',field('invoice_no','Invoice number','','text','required')+field('reference','Bank / payment reference','','text','required minlength="5"')+field('amount','Actual amount received','','number','required min="0.01" step="0.01"')+area('note','How the receipt was reconciled','','required minlength="10"')+check('confirm','I checked the payment evidence against this invoice.'),'Record receipt'))+card('Receipt history',d.receipts.map(x=>`<article class="flow-card"><b>${e(x.invoice_no)} · ${e(x.state)}</b><p>${e(x.reference)} · $${Number(x.amount).toFixed(2)}</p><p>${e(x.note)}</p>${x.state==='exception'?form('receipt-resolve',area('note','Reconciliation outcome','','required minlength="20"')+check('confirm','I reviewed this mismatch. Closing it does not mark the invoice paid.'),'Record review',`data-id="${x.id}"`):''}</article>`).join('')||empty('No receipt evidence yet.'));};
 panels.metrics=async()=>{const from=q().get('from')||'',to=q().get('to')||'';const d=await call('/admin/journey-metrics?from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to));return form('metrics-range',field('from','From',from,'date')+field('to','To',to,'date'),'Compare reporting period')+card('Where time is spent',`<p>${e(d.note)}</p><div class="flow-table"><table><thead><tr><th>Task</th><th>Owner</th><th>Count</th><th>Median wait (h)</th><th>P90 wait (h)</th></tr></thead><tbody>${d.tasks.map(r=>`<tr><td>${e(r.kind)}</td><td>${e(r.owner_kind)}</td><td>${r.count}</td><td>${Number(r.median_hours||0).toFixed(1)}</td><td>${Number(r.p90_hours||0).toFixed(1)}</td></tr>`).join('')}</tbody></table></div><h3>Activity and rework</h3>${d.events.map(r=>`<p>${e(r.task_kind)} · ${e(r.event)} · ${r.count}</p>`).join('')}`);};
 panels.settings=async()=>{const d=await call('/admin/journey-settings');return card('Payroll cutover',`<p>Confirm the first date of work not already processed in your external payroll. Scheduled drafts start only after this setup. Historical manual batches require individual review.</p>${form('payroll-settings',select('payroll_drafts_enabled','Scheduled draft preparation',[['false','Off until reconciled'],['true','Enabled after cutover review']],String(d.payroll_drafts_enabled))+field('payroll_cutover_date','First unprocessed work date',d.payroll_cutover_date,'date'),'Save payroll setup')}`)+card('Private invoice tax settings','<p>Private invoices are automatic. Choose the applicable business tax treatment; this does not hold individual invoices.</p>'+form('private-settings',select('private_gst_percent','Tax treatment',[['0','No GST'],['10','10% GST included in displayed prices']],d.private_gst_percent)+area('private_billing_evidence','Basis / reference (optional)',d.private_billing_evidence),'Save tax settings'))+card('Optional document assistance',`<p>Configure the provider and model in AI settings, then record its specific contract and processing controls in <a href="#/admin/assurance">Launch & operations</a>. The operator must also allow the exact endpoint. A region label alone does not enable document processing.</p>${form('ai-settings',select('ai_document_processing','Document processing',[['false','Off'],['true','Approved']],String(d.ai_document_processing))+area('ai_processing_evidence','Processing arrangement and approval evidence',d.ai_processing_evidence,'minlength="20"'),'Save processing approval')}<p><a href="#/admin/ai">AI configuration and review</a></p>`);};
 async function bookAgain(template){const d=await call('/workers/'+Number(template.worker_id));const worker=d.worker||d;if(!worker.id)throw Error('This worker is no longer available. Choose another worker.');openBookingModal(worker);el('bkService').value=template.service;el('bkStart').value=template.start;el('bkHours').value=template.hours;el('bkDate').value='';el('bkNotes').value='';el('bkSleep').checked=!!template.sleepover;el('bkRepeat').value='';el('bkIntro').checked=false;syncSleepoverOption();syncRepeatUI();syncBkRateLine();el('bkDate').focus();}
 async function prepareSeriesEnd(id){const r=await call('/journey/series/'+id+'/end-preview');const yes=await dialog('Review ending these visits',`<p>These ${r.visits.length} future visits will be cancelled. Detached visits and past records remain.</p>${r.visits.map(v=>`<p>${e(fmtAU(v.date))} at ${e(v.start)} · ${v.hours} hours${v.may_charge?' · <strong>May carry the published short-notice charge</strong>':' · No short-notice charge'}</p>`).join('')}<label><input type="checkbox" data-confirm-end> I have reviewed each visit and any possible charge.</label>`,'End these visits',d=>{if(!d.querySelector('[data-confirm-end]').checked)throw Error('Confirm the visits and charges first.');return true;});return yes?{confirm:true,token:r.token,expires:r.expires}:null;}
 async function availability(patch){const r=await call('/journey/availability-preview',{patch});const result=await dialog('Review your availability change',r.affected.length?`<p>These visits fall outside your new hours or leave. Select those for which the office should arrange cover. Unselected visits remain your commitment.</p>${r.affected.map(v=>`<p><label><input type="checkbox" name="cover" value="${v.id}"> ${e(fmtAU(v.date))} at ${e(v.start)} · ${v.hours} hours${v.urgent?' · office contact needed':''}</label></p>`).join('')}`:'<p>No existing visits are affected.</p>','Confirm availability',d=>[...d.querySelectorAll('[name=cover]:checked')].map(x=>Number(x.value)));if(result===null)return false;await call('/journey/availability',{patch,confirm:true,cover_ids:result,token:r.token,expires:r.expires});return true;}
 const actions={
   login:()=>openModal('#loginModal'),
   refresh:()=>render(),
   'resend-email':async()=>{const context=snapshot(),hash=location.hash;const r=await call('/resend-verification',{});if(context!==snapshot()||hash!==location.hash)return;if(r.already){API.me.verified=true;await render();return;}const out=el('naStatus');if(out)out.textContent='Verification email requested. Check your inbox and spam folder. If it does not arrive, contact the office.';}, 'refresh-account':()=>refreshCurrent(),
   'activate-worker':async b=>{await call('/admin/workers/'+b.dataset.id+'/approve',{});toast('Worker activated.');await render();},
   'book-interview':async b=>{await call('/journey/interview',{slot_id:Number(b.dataset.id),revision:Number(b.dataset.revision)});await render();},
   'cancel-interview':async()=>{if(await dialog('Cancel this interview?','<p>The time will become available to another applicant.</p>','Cancel interview')){await call('/journey/interview',{cancel:true});await render();}},
   'accept-visit':async b=>{const d=await call('/journey/bookings/'+b.dataset.id);const proof=await dialog('Read the brief and accept',brief(d.brief)+(d.plan_id?'<label><input type="checkbox" data-plan-read> I have read and can follow this plan version.</label>':''),'Accept visit',x=>{if(d.plan_id&&!x.querySelector('[data-plan-read]').checked)throw Error('Read and confirm the plan before accepting.');return {plan_ack:!!d.plan_id,plan_id:d.plan_id,plan_version:d.plan_version};});if(proof){await call('/bookings/'+b.dataset.id,{status:'accepted',...proof},'PATCH');await render();}},
   'decline-visit':async b=>{if(await dialog('Decline this request?','<p>The participant will be told you cannot take this visit.</p>','Decline request')){await call('/bookings/'+b.dataset.id,{status:'declined'},'PATCH');await render();}},
   'complete-visit':async b=>{const f=b.closest('[data-note-form]');await BookItReview.saveDraft(f,true);const payload={status:'completed',note:f.querySelector('.note-body').value,scope:f.querySelector('input[type=radio]:checked').value==='yes',scope_detail:f.querySelector('.note-scope-detail').value};if(f.querySelector('.note-active'))Object.assign(payload,{active_hours:f.querySelector('.note-active').value,active_note:f.querySelector('.note-active-note').value});Object.assign(payload,{km:f.querySelector('.note-km').value,km_from:f.querySelector('.note-km-from').value,km_to:f.querySelector('.note-km-to').value});await call('/bookings/'+b.dataset.id,payload,'PATCH');BookItReview.finishDraft(f);toast('Shift completed. The participant can now approve it; invoicing follows automatically.');await render();},
   'approve-visit':async b=>{if(await dialog('Approve this timesheet?','<p>Confirm that you have reviewed the time, charges and worker’s note.</p>','Approve')){await call('/bookings/'+b.dataset.id,{status:'approved'},'PATCH');location.hash='#/journey?panel=reviews';}},
   'accept-series':async b=>{const f=el('flowSeries'),ids=[...f.querySelectorAll('[name=visit]:checked')].map(x=>Number(x.value));if(!ids.length)throw Error('Choose the visits you can work.');if(seriesData.plan_id&&!f.querySelector('[name=read]').checked)throw Error('Read and confirm this plan version.');await call('/journey/series/'+b.dataset.id+'/accept',{ids,revisions:Object.fromEntries(seriesData.visits.map(v=>[v.id,v.revision])),plan_ack:!!seriesData.plan_id,plan_id:seriesData.plan_id,plan_version:seriesData.plan_version});toast(ids.length+' visits accepted.');location.hash='#/journey';},
   'plan-changes':async b=>{const d=await call('/journey/bookings/'+b.dataset.id+'/plan-changes');await dialog('Changes since your last review',d.previous_version?`<p>Version ${d.previous_version} → ${d.version}. Read the full current brief before accepting a visit.</p>${d.changes.map(x=>`<h3>${e(x.title)}</h3><p>Previously: ${e(x.before)}</p><p>Now: ${e(x.after)}</p>`).join('')||empty('No changes in the operational fields.')}`:'<p>This is your first review. Read the current brief.</p>','Close');},
   'book-again':async b=>{const d=await call('/journey/bookings/'+b.dataset.id);await bookAgain(d.booking);},
   'save-routine':async b=>{const label=await dialog('Save a usual visit',field('label','Name this routine','My usual visit'),'Save',d=>d.querySelector('[name=label]').value);if(label){await call('/journey/routines',{booking_id:Number(b.dataset.id),label});toast('Usual visit saved.');}},
   'use-routine':b=>bookAgain(CareFlow.routines.find(r=>r.id===Number(b.dataset.id)).data),
   'delete-routine':async b=>{await call('/journey/routines/'+b.dataset.id,{},'DELETE');await render();},
   'create-calendar':async()=>{if(!await dialog('Share visit times with your calendar?','<p>Your calendar service will receive generic visit times. Keep this subscription link private.</p>','Create link'))return;const d=await call('/journey/calendar',{confirm:true});el('flowCalendarLink').innerHTML=`<p>Copy this secret URL into your calendar’s “Subscribe from URL” option.</p><label class="flow-field">Private subscription URL<input readonly value="${e(d.url)}" aria-label="Private calendar subscription URL"></label><p>Expires ${e(fmtAU(d.expires_at.slice(0,10)))}.</p>`;},
   'revoke-calendar':async b=>{await call('/journey/calendar/'+b.dataset.id,{},'DELETE');await refreshCurrent();},
   'retry-delivery':async b=>{await call('/admin/deliveries/'+b.dataset.id+'/retry',{});await render();},
   'approve-payroll':async b=>{if(await dialog('Approve this pay batch?','<p>A different reviewer must approve this batch. Confirm the reviewed gross wages, super, allowances, roster entitlements and external payroll calculation. Booking allocations are estimates. Approval does not transfer money.</p>','Approve batch')){await call('/admin/payroll-batches/'+b.dataset.id+'/approve',{confirm:true});await render();}},
   'reopen-payroll':async b=>{const reason=await dialog('Reopen this batch',area('reason','Reason'),'Reopen',d=>{const x=d.querySelector('textarea').value;if(x.trim().length<15)throw Error('Record a reason in at least 15 characters.');return x;});if(reason){await call('/admin/payroll-batches/'+b.dataset.id+'/reopen',{reason});await render();}},
   'end-series':async b=>{const body=await prepareSeriesEnd(b.dataset.id);if(body){await call('/series/'+b.dataset.id+'/end',body);await render();}},
   'assist-document':async b=>{if(await dialog('Read this document?','<p>A copy of this document will be sent to the office-approved processing endpoint. You must check the original and confirm every proposed value. This does not verify the credential.</p>','Read document')){await call('/journey/assistance/document',{doc_id:Number(b.dataset.id),consent:true});await refreshCurrent();}}
 };
 const submits={
   'metrics-range':async(f,b)=>{location.hash='#/journey?panel=metrics&from='+encodeURIComponent(b.from)+'&to='+encodeURIComponent(b.to);},
   'payroll-settings':async(f,b)=>{await call('/admin/journey-settings',{...b,payroll_drafts_enabled:b.payroll_drafts_enabled==='true'});status(f,'Payroll cutover saved.');},
   'provider-review':async(f,b)=>{await call('/admin/finance/provider-events/review',{...b,event_id:f.dataset.event,confirm:f.elements.confirm.checked});await render();},
   receipt:async(f,b)=>{const r=await call('/admin/finance/receipt',{...b,amount:Number(b.amount),confirm:f.elements.confirm.checked});status(f,r.message);},
   'receipt-resolve':async(f,b)=>{await call('/admin/finance/receipts/'+f.dataset.id+'/resolve',{note:b.note,confirm:f.elements.confirm.checked});await render();},
   'queue-search':async(f,b)=>{location.hash='#/journey?panel=tasks&search='+encodeURIComponent(b.search);},
   'choose-worker':async(f,b)=>{location.hash='#/journey?panel=recruitment&worker='+Number(b.worker);},
   'shared-contacts':async(f,b)=>{const r=await call('/journey/intake',{data:b,revision:Number(f.dataset.revision),contacts_only:true},'PUT');f.dataset.revision=r.revision;status(f,'Contact details saved.');},
   'intake':async(f,b)=>{const r=await call('/journey/intake',{data:b,revision:Number(f.dataset.revision),account_revision:f.dataset.accountRevision},'PUT');f.dataset.revision=r.revision;f.dataset.accountRevision=r.account_revision;status(f,'Details confirmed and saved.');if(API.me.id===subject())Object.assign(API.me,{name:b.name,phone:b.phone,suburb:b.suburb});},
   'billing':async(f,b)=>{if(b.plan==='private')Object.assign(b,{ndis_number:'',pm_email:'',plan_start:'',plan_end:''});let r;try{r=await call('/me/billing',b);}catch(err){if(!err.data?.needs_confirm)throw err;if(!await dialog('Review the payer change',`<p>${e(err.message)}</p>`,'Confirm change'))return;r=await call('/me/billing',{...b,confirm:true});}if(API.me.role==='participant')API.me=r.user;status(f,'Funding details saved.');},
   'task-owner':async(f,b)=>{await call('/admin/journey-tasks',{task_key:f.dataset.key,owner_id:Number(b.owner_id),due_at:b.due_at?b.due_at+'T23:59:59Z':null},'PATCH');status(f,'Owner and due date saved.');},
   'recruit-review':async(f,b)=>{await call('/admin/recruitment/checks',{worker_id:Number(f.dataset.worker),check_key:f.dataset.key,...b});status(f,'Review recorded.');},
   'interview-slot':async(f,b)=>{await call('/admin/interview-slots',{starts_at:new Date(b.starts_at).toISOString(),ends_at:new Date(b.ends_at).toISOString()});status(f,'Interview time published.');},
   'query-visit':async(f,b)=>{await call('/bookings/'+f.dataset.id,{status:'queried',query_note:b.question},'PATCH');toast('Question sent. The approval clock is paused.');await render();},
   'reply-query':async(f,b)=>{await call('/bookings/'+f.dataset.id+'/notes',{note:b.body,scope:false});toast('Answer filed.');await render();},
   'incident':async(f,b)=>{const d=CareFlow.shift;await call('/incidents',{...b,harm:b.harm==='unknown'?null:b.harm==='yes',booking_id:Number(f.dataset.id),event_key:f.dataset.event,participant_name:data.role==='worker'?d.other_name:data.subject?.name,worker_name:data.role==='worker'?API.me.name:d.other_name});f.querySelectorAll('input,textarea,button,select').forEach(x=>x.disabled=true);status(f,'Incident filed and linked to this visit.');},
   'followup':async(f,b)=>{const r=await call('/journey/followup',{booking_id:Number(f.dataset.id),...b});if(r.next==='book-again'){toast('Your preference is saved. Choose a new date when ready.');location.hash='#/journey?panel=shift&booking='+f.dataset.id;}else{toast('The office will follow up with you.');location.hash='#/journey?panel=transitions';}},
   'preferences':async(f,b)=>{const p={digest:f.elements.digest.checked,quiet_from:b.quiet_from,quiet_to:b.quiet_to};if(b.approval_owner)p.approval_owner=Number(b.approval_owner);await call('/journey/preferences',p,'PUT');status(f,'Preferences saved.');},
   'transition':async(f,b)=>{await call('/journey/transition',b);toast('Change request sent to the office.');await render();},
   'transition-close':async(f,b)=>{await call('/admin/transitions/'+f.dataset.id,{close:true,owner_id:Number(b.owner_id),outcome:b.outcome,confirm:f.elements.confirm.checked,reviewed_visit_ids:f.dataset.visits?f.dataset.visits.split(',').map(Number):[]});await render();},
   'payroll-prepare':async(f,b)=>{const d=await call('/admin/payroll-batches',b);if(d.id)location.hash='#/journey?panel=payroll&batch='+d.id;else status(f,d.message);},
   'payroll-line':async(f,b)=>{await call('/admin/payroll-lines/'+f.dataset.id+'/review',b);status(f,'Line review saved.');},
   'payroll-adjustment':async(f,b)=>{await call('/admin/payroll-batches/'+f.dataset.id+'/adjustment',{...b,worker_id:Number(b.worker_id),amount:Number(b.amount)});await render();},
   'payroll-ack':async(f,b)=>{await call('/admin/payroll-batches/'+f.dataset.id+'/acknowledge',{external_ref:b.external_ref,confirm:f.elements.confirm.checked});await render();},
   'private-settings':async(f,b)=>{await call('/admin/journey-settings',{...b,private_billing_ready:false});status(f,'Tax settings saved.');},
   'ai-settings':async(f,b)=>{await call('/admin/journey-settings',{...b,ai_document_processing:b.ai_document_processing==='true'});status(f,'Processing approval saved.');},
   'assist-review':async(f,b)=>{await call('/journey/assistance/'+f.dataset.id+'/review',{...b,confirm:f.elements.confirm.checked});await refreshCurrent();}
 };
 document.addEventListener('click',async ev=>{const task=ev.target.closest('[data-flow-task]');if(task){activeTask=task.dataset.flowTask;activeSubject=snapshot();lastInput=Date.now();call('/journey/events',{task_key:activeTask,event:'started',event_key:crypto.randomUUID()}).catch(()=>{});}const b=ev.target.closest('[data-flow-action]');if(!b||!actions[b.dataset.flowAction])return;ev.preventDefault();const context=snapshot();b.disabled=true;try{await actions[b.dataset.flowAction](b);}catch(err){if(context===snapshot()){toast(err.message);let out=b.closest('.flow-card,.na-task,.na-office-row')?.querySelector('[data-flow-error]');if(!out&&b.closest('.flow-card,.na-task,.na-office-row')){out=document.createElement('p');out.className='flow-error';out.dataset.flowError='';out.setAttribute('role','alert');b.closest('.flow-card,.na-task,.na-office-row').append(out);}if(out)out.textContent=err.message;}}finally{if(b.isConnected)b.disabled=false;}});
 document.addEventListener('submit',async ev=>{const f=ev.target.closest('[data-flow-form]');if(!f)return;ev.preventDefault();if(f.dataset.saving==='true')return;f.dataset.saving='true';const b=Object.fromEntries(new FormData(f)),btn=f.querySelector('[type=submit]'),context=snapshot();btn.disabled=true;try{track('submitted');await submits[f.dataset.flowForm](f,b);track('saved');}catch(err){track('failed');if(context===snapshot())status(f,err.message,true);}finally{f.dataset.saving='false';if(btn.isConnected&&!f.querySelector('[data-flow-status]')?.textContent.startsWith('Incident filed'))btn.disabled=false;}});
 function track(action){if(activeTask&&activeSubject===snapshot()&&API.me)call('/journey/events',{task_key:activeTask,event:action,event_key:crypto.randomUUID()}).catch(()=>{});}
 document.addEventListener('visibilitychange',()=>track(document.visibilityState==='visible'?'resumed':'returned'));
 document.addEventListener('input',()=>{lastInput=Date.now();});
 setInterval(()=>{if(activeTask&&activeSubject===snapshot()&&API.me&&document.visibilityState==='visible'&&Date.now()-lastInput<30000)call('/journey/events',{task_key:activeTask,event:'effort',duration_ms:15000,event_key:crypto.randomUUID()}).catch(()=>{});},15000);
 function nav(){const n=el('navJourney');if(n)n.hidden=!(API.online&&API.me);}
 function restoreBooking(){try{const p=JSON.parse(sessionStorage.getItem('careweb-booking-choice')||'null');if(p&&p.expires>Date.now()&&p.subject===snapshot()){for(const [k,id]of Object.entries({service:'bkService',date:'bkDate',start:'bkStart',hours:'bkHours'}))if(p[k])el(id).value=p[k];syncSleepoverOption();syncBkRateLine();}}catch{}try{const saved=JSON.parse(sessionStorage.getItem('careweb-match-preferences')||'null');if(saved&&saved.expires>Date.now()&&!sessionStorage.getItem('careweb-booking-choice')){const f=new URLSearchParams(saved.query);for(const [k,id]of Object.entries({service:'bkService',date:'bkDate',start:'bkStart',hours:'bkHours'}))if(f.get(k))el(id).value=f.get(k);}}catch{}}
 function rememberBooking(){if(!bookingWorker||!API.me)return;try{sessionStorage.setItem('careweb-booking-choice',JSON.stringify({subject:snapshot(),worker:bookingWorker.id,service:el('bkService').value,date:el('bkDate').value,start:el('bkStart').value,hours:el('bkHours').value,expires:Date.now()+864e5}));}catch{}}
 document.addEventListener('change',ev=>{if(ev.target.closest('#bookingForm'))rememberBooking();});
 async function alternatives(body){const d=await call('/journey/alternatives',body);if(!d.options.length){toast('No nearby matching times found. Try another worker or ask the office.');return;}const chosen=await dialog('Other available times',`<p>These options are estimates and will be checked again when requested.</p>${d.options.map((x,i)=>`<p><label><input type="radio" name="option" value="${i}"> ${e(fmtAU(x.date))} at ${e(x.start)}</label></p>`).join('')}`,'Use this time',f=>{const v=f.querySelector('[name=option]:checked');if(!v)throw Error('Choose a time.');return d.options[Number(v.value)];});if(chosen){el('bkDate').value=chosen.date;el('bkStart').value=chosen.start;rememberBooking();}}
 async function paymentProof(path,body){const out=await dialog(body.paid===false?'Reverse a recorded payment':'Record invoice payment',field('reference','Unique bank / correction reference')+field('amount','Amount','','number','step="0.01"')+area('note','Evidence and reason'),'Confirm reviewed receipt',d=>{const reference=d.querySelector('[name=reference]').value,amount=Number(d.querySelector('[name=amount]').value),note=d.querySelector('[name=note]').value;if(reference.length<5||!amount||note.length<10)throw Error('Enter a reference, amount and evidence.');return {reference,amount,note,confirm:true};});return out;}
 return {render,renderContacts,renderPreferences,documentAssistance,nav,dialog,paymentProof,availability,prepareSeriesEnd,restoreBooking,rememberBooking,alternatives};
})();
